import type {IncomingMessage, ListSessionsMessage} from '../../types/messages.js';

const MAX_CONTENT_LENGTH = 10000;

interface ValidationSuccess {
  valid: true;
  data: IncomingMessage;
}

interface ValidationFailure {
  valid: false;
  error: string;
}

export type ValidationResult = ValidationSuccess | ValidationFailure;

// eslint-disable-next-line camelcase -- protocol message types use snake_case
const VALIDATORS: Record<string, (message: Record<string, unknown>) => ValidationResult> = {
  // eslint-disable-next-line camelcase -- protocol message types use snake_case
  user_message: validateUserMessage,
  ping: validatePingMessage,
  // eslint-disable-next-line camelcase -- protocol message types use snake_case
  list_sessions: validateListSessionsMessage,
};

export function validateMessage(payload: unknown): ValidationResult {
  if (typeof payload !== 'object' || payload === null) {
    return {valid: false, error: 'Message must be an object'};
  }

  const message = payload as Record<string, unknown>;

  if (typeof message.type !== 'string') {
    return {valid: false, error: 'Message must have a type field'};
  }

  const validator = VALIDATORS[message.type as string];
  if (!validator) {
    return {valid: false, error: `Unknown message type: ${message.type}`};
  }

  return validator(message);
}

function validateUserMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.content !== 'string') {
    return {valid: false, error: 'user_message must have content string'};
  }

  const trimmed = message.content.trim();

  if (trimmed.length === 0) {
    return {valid: false, error: 'Message content cannot be empty'};
  }

  if (message.content.length > MAX_CONTENT_LENGTH) {
    return {valid: false, error: `Message content too long (max ${MAX_CONTENT_LENGTH} chars)`};
  }

  return {
    valid: true,
    data: {
      type: 'user_message',
      content: message.content,
    },
  };
}

function validatePingMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.timestamp !== 'number') {
    return {valid: false, error: 'ping must have timestamp number'};
  }

  return {
    valid: true,
    data: {
      type: 'ping',
      timestamp: message.timestamp,
    },
  };
}

function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  const listSessionsMessage: ListSessionsMessage = {type: 'list_sessions'};

  if (message.limit !== undefined) {
    if (!isValidLimit(message.limit)) {
      return {valid: false, error: 'list_sessions limit must be an integer between 1 and 200'};
    }
    listSessionsMessage.limit = message.limit as number;
  }

  if (message.before !== undefined) {
    const cursorError = validateListSessionsCursor(message.before);
    if (cursorError) {
      return {valid: false, error: cursorError};
    }
    const before = message.before as Record<string, unknown>;
    listSessionsMessage.before = {
      sessionId: before.sessionId as string,
      updatedAt: before.updatedAt as string | number,
    };
  }

  return {
    valid: true,
    data: listSessionsMessage,
  };
}

function isValidLimit(limit: unknown): limit is number {
  return typeof limit === 'number' && Number.isInteger(limit) && limit >= 1 && limit <= 200;
}

function validateListSessionsCursor(cursor: unknown): string | null {
  if (typeof cursor !== 'object' || cursor === null) {
    return 'list_sessions before must be an object';
  }
  const before = cursor as Record<string, unknown>;
  if (!isValidSessionId(before.sessionId)) {
    return 'list_sessions before.sessionId must be a string between 1 and 128 characters';
  }
  if (!isValidUpdatedAt(before.updatedAt)) {
    return 'list_sessions before.updatedAt must be a string or number';
  }
  return isFiniteDate(before.updatedAt) ? null : 'list_sessions before.updatedAt must be a valid date';
}

function isValidSessionId(sessionId: unknown): sessionId is string {
  return typeof sessionId === 'string' && sessionId.length >= 1 && sessionId.length <= 128;
}

function isValidUpdatedAt(updatedAt: unknown): boolean {
  return typeof updatedAt === 'string' || typeof updatedAt === 'number';
}

function isFiniteDate(value: unknown): boolean {
  const parsed = typeof value === 'string' ? Date.parse(value as string) : (value as number);
  return !isNaN(parsed) && isFinite(parsed);
}

